nextflow_process {

    name "Test Process FASTQSCREEN_BUILDFROMINDEX"
    script "../main.nf"
    process "FASTQSCREEN_BUILDFROMINDEX"

    tag "modules"
    tag "modules_nfcore"
    tag "fastqscreen"
    tag "fastqscreen/buildfromindex"
    tag "bowtie2/build"

    setup {

        run("BOWTIE2_BUILD") {
            script "../../../bowtie2/build/main.nf"
            process {
                """
                input[0] = channel.of([
                    [id: "sarscov2"],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ], [
                    [id: "human"],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta', checkIfExists: true)
                ])
                """
            }
        }
    }

    test("sarscov2 - human") {

        when {
            process {
                """
                // Databases must be passed in a fixed order (sarscov2, human); collect() follows build completion order
                input[0] = BOWTIE2_BUILD.out.index.toSortedList { a, b -> b[0].id <=> a[0].id }.map { items -> items.collect { item -> item[0].id } }
                input[1] = BOWTIE2_BUILD.out.index.toSortedList { a, b -> b[0].id <=> a[0].id }.map { items -> items.collect { item -> item[1] } }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("sarscov2 - human - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = BOWTIE2_BUILD.out.index.toSortedList { a, b -> b[0].id <=> a[0].id }.map { items -> items.collect { item -> item[0].id } }
                input[1] = BOWTIE2_BUILD.out.index.toSortedList { a, b -> b[0].id <=> a[0].id }.map { items -> items.collect { item -> item[1] } }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}
